/**
 * 🎮 AmratGames Game & Provably Fair Type Contracts
 * Definitive cryptographic commitments, round sessions, and bet evaluation interfaces.
 */

export type SupportedCurrency = 'INR' | 'USDT' | 'BTC' | 'AMRAT'

export type GameSlug = 
    | 'crash' 
    | 'dino' 
    | 'color-match' 
    | 'dragon-tiger' 
    | 'coin-toss' 
    | 'pvp-duel'

export interface ProvablyFairCommitment {
    /** 32-byte secret hex seed generated by the server before the round */
    serverSeed: string
    /** SHA-256 hash of serverSeed, committed to the player before wager placement */
    serverSeedHash: string
    /** Player-provided client seed (entropy input) */
    clientSeed: string
    /** Incrementing sequential round counter */
    nonce: number
    /** HMAC-SHA256 signature binding serverSeed, clientSeed, and nonce */
    hash: string
}

export interface BetEvaluationResult {
    /** Canonical game slug identifier */
    game: string
    /** Win/loss outcome (True if payout > 0 and net-positive) */
    won: boolean
    /** Multiplier applied to original wager (e.g., 2.0x, 1.98x) */
    multiplier: number
    /** Total gross credit return to the player wallet */
    payout: number
    /** Net gain/loss: payout - betAmount */
    profit: number
    /** Flag indicating single-round bankroll profit cap was enforced */
    wasCapped?: boolean
    /** Maximum allowed profit ceiling at evaluation time */
    maxProfitCap?: number
    /** Cryptographic outcome verification hash */
    hash: string
    /** Game-specific contextual outcome details (cards, crash multiplier, dice outcome) */
    roundData?: Record<string, any>
}

export interface BetPayload {
    userId: string
    currency?: SupportedCurrency
    betAmount: number
    game: string
    gameName: string
    evaluator: (ctx: { user: any, betAmount: number, currency: SupportedCurrency }) => Promise<BetEvaluationResult> | BetEvaluationResult
}

export interface BetRecord {
    id: string
    userId: string
    username: string
    game: string
    gameName: string
    currency: SupportedCurrency
    betAmount: number
    multiplier: number
    payout: number
    profit: number
    won: boolean
    hash: string
    roundData?: Record<string, any>
    timestamp: string
}

export interface DinoRoundSession {
    roundId: string
    userId: string
    currency: SupportedCurrency
    betAmount: number
    difficulty: 'easy' | 'medium' | 'hard'
    obstaclesCleared: number
    stepNonce: number
    currentMultiplier: number
    active: boolean
    startedAt: number
}

export interface CrashRoundSession {
    roundId: string
    userId: string
    currency: SupportedCurrency
    betAmount: number
    crashPoint: number
    autoCashout: number | null
    startedAt: number
    active: boolean
}

export interface ColorMatchBet {
    color: 'red' | 'green' | 'violet' | number
    amount: number
    multiplier: number
    won?: boolean
    payout?: number
}

export interface PvPDuelSession {
    id: string
    creatorId: string
    creatorUsername: string
    opponentId?: string | null
    opponentUsername?: string | null
    stakeAmount: number
    currency: SupportedCurrency
    status: 'waiting' | 'accepted' | 'resolved' | 'cancelled'
    winnerId?: string | null
    winnerPayout?: number
    houseRake?: number
    serverSeed: string
    clientSeed: string
    createdAt: string
}
